import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** Total processing attempts before a job is marked failed. */
export const MAX_ATTEMPTS = 3;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as stored. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

/** The job JSON shape returned by the API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function one(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): JobRow | undefined {
  return db.prepare(sql).get(...params) as JobRow | undefined;
}

function many(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): JobRow[] {
  return db.prepare(sql).all(...params) as JobRow[];
}

function nowIso(): string {
  return new Date().toISOString();
}

export function findJobById(db: DatabaseSync, id: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE id = ?', id);
}

export function findJobByKey(db: DatabaseSync, key: string): JobRow | undefined {
  return one(db, 'SELECT * FROM jobs WHERE idempotency_key = ?', key);
}

export function listJobs(db: DatabaseSync): JobRow[] {
  return many(db, 'SELECT * FROM jobs ORDER BY seq DESC');
}

export function insertJob(
  db: DatabaseSync,
  job: { input: string; steps: number; failAttempts: number; idempotencyKey: string | null },
): JobRow {
  const id = randomUUID();
  const ts = nowIso();
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
                       idempotency_key, run_after, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ).run(id, job.input, job.steps, job.failAttempts, job.idempotencyKey, ts, ts);
  return findJobById(db, id)!;
}

/**
 * Moves the oldest runnable queued job to `running` and counts the new attempt.
 * Runs in an immediate transaction so two workers can never claim the same job.
 */
export function claimNextJob(db: DatabaseSync, nowMs: number = Date.now()): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  let claimed: JobRow | undefined;
  try {
    const next = one(
      db,
      `SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`,
      nowMs,
    );
    if (next) {
      db.prepare(
        `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
         WHERE id = ?`,
      ).run(nowIso(), next.id);
      claimed = findJobById(db, next.id);
    }
    db.exec('COMMIT');
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction was open
    }
    throw err;
  }
  return claimed;
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(
    completed,
    nowIso(),
    id,
  );
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ?
     WHERE id = ?`,
  ).run(output, nowIso(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string, attempts: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, attempts = ?, updated_at = ?
     WHERE id = ?`,
  ).run(error, attempts, nowIso(), id);
}

/** Returns a failed attempt's job to `queued`, not runnable before `runAfterMs`. */
export function scheduleRetry(db: DatabaseSync, id: string, runAfterMs: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ?`,
  ).run(runAfterMs, nowIso(), id);
}

/** Undoes a claim when the worker stops before the attempt finishes; the attempt is not counted. */
export function revertToQueued(db: DatabaseSync, id: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress_completed = 0, run_after = 0,
                     updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(nowIso(), id);
}

/** Jobs left `running` by a worker that died are queued again so they are processed again. */
export function requeueInterrupted(db: DatabaseSync): number {
  const result = db
    .prepare(
      `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ?
       WHERE status = 'running'`,
    )
    .run(nowIso());
