export interface FieldError {
  field: string;
  message: string;
}

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export type ValidationResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
export const MAX_INPUT_LENGTH = 1000;

function integerField(
  body: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number {
  if (!Object.hasOwn(body, name)) return fallback;
  const value = body[name];
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return fallback;
  }
  if (value < min || value > max) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
  }
  return value;
}

/** Validates a parsed JSON object body and applies defaults. Returns every problem found. */
export function validateSubmission(body: Record<string, unknown>): ValidationResult {
  const fields: FieldError[] = [];
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const input = body.input;
  if (typeof input !== 'string') {
    fields.push({ field: 'input', message: 'input is required and must be a string' });
  } else if (input.trim() === '') {
    fields.push({ field: 'input', message: 'input must not be blank' });
  } else if (input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `input must be at most ${MAX_INPUT_LENGTH} characters` });
  }

  const steps = integerField(body, 'steps', 1, 20, 5, fields);
  const failAttempts = integerField(body, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0 || typeof input !== 'string') return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

