  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      revertToQueued(db, job.id);
      return;
    }
    setProgress(db, job.id, step);
    beat();
  }
  completeJob(db, job.id, job.input.toUpperCase());
}

requeueInterrupted(db);
beat(true);
console.log('worker started');

while (!stopping) {
  try {
    beat();
    const job = claimNextJob(db);
    if (job) await processJob(job);
    else await sleep(IDLE_POLL_MS);
  } catch (err) {
    console.error('worker error:', err);
    await sleep(IDLE_POLL_MS);
  }
}

clearHeartbeat(db);
db.close();
console.log('worker stopped');
process.exit(0);

